```

### 预加载（Preload）策略

```tsx
const Dashboard = lazy(() => import('./pages/Dashboard'));

function Nav() {
  const preloadDashboard = () => {
    import('./pages/Dashboard');
  };

  return (
    <nav>
      <Link to="/">首页</Link>
      <Link to="/dashboard" onMouseEnter={preloadDashboard} onFocus={preloadDashboard}>
        仪表板
      </Link>
    </nav>
  );
}
```

